use std::net::{ToSocketAddrs, IpAddr};
use std::process::{Command, Stdio};
use std::time::Duration;
use clap::Parser;
use anyhow::{Context, bail};

#[derive(Parser, Debug)]
#[command(
    name = "gping",
    version = "1.20.1",
    long_version = "gping 1.20.1\ncommit_hash: 42449c03\nbuild_time: 2026-08-10 23:10:43 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu",
