    if let Err(e) = run_tui(&args, watch_interval) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }

    // Cleanup children
    for mut child in children {
        let _ = child.kill();
        let _ = child.wait();
    }

    // Handle --clear
    if args.clear {
        // Clear screen
        use crossterm::execute;
        use crossterm::terminal::{Clear, ClearType};
        let _ = execute!(std::io::stdout(), Clear(ClearType::All));
    }
}

fn run_tui(args: &Args, watch_interval: f64) -> anyhow::Result<()> {
    use crossterm::{
        event::{self, Event, KeyCode},
        execute,
        terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Constraint, Direction, Layout},
        widgets::{Block, Borders, Paragraph},
        Terminal,
    };
    use std::io;

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut should_quit = false;
    while !should_quit {
        terminal.draw(|f| {
            let size = f.area();
            // Apply margins
            let vertical = args.vertical_margin as u16;
            let horizontal = args.horizontal_margin as u16;
            let inner = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(vertical),
                    Constraint::Min(0),
                    Constraint::Length(vertical),
                ])
                .split(size);
            let middle = inner[1];
            let horiz = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Length(horizontal),
                    Constraint::Min(0),
                    Constraint::Length(horizontal),
                ])
                .split(middle);
            let area = horiz[1];

            let block = Block::default().title("gping").borders(Borders::ALL);
            // Simple content showing hosts
            let hosts_text = if args.hosts.is_empty() {
                "No hosts".to_string()
            } else {
                args.hosts.join(", ")
            };
            let paragraph = Paragraph::new(format!("Hosts: {}\nBuffer: {}s Interval: {}s\nPress 'q' to quit", hosts_text, args.buffer, watch_interval))
                .block(block);
            f.render_widget(paragraph, area);
        })?;

        // Poll for events with timeout = watch_interval
        let timeout = Duration::from_secs_f64(watch_interval);
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                    should_quit = true;
                }
                // Also handle Ctrl+C
                if key.code == KeyCode::Char('c') && key.modifiers.contains(event::KeyModifiers::CONTROL) {
                    should_quit = true;
                }
            }
        }
        // For ping mode, we would update graph data here
        // For now just loop
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}
