EOF
cat Cargo.toml
mkdir -p src
cat > src/main.rs <<'RS'
use std::net::{ToSocketAddrs, IpAddr};
use std::process::{Command, Stdio};
use std::time::Duration;
use clap::{Parser, Command as ClapCommand, Arg, ArgAction};
use anyhow::{Context, bail};

fn build_cli() -> ClapCommand {
    ClapCommand::new("gping")
        .version("1.20.1")
        .long_version("gping 1.20.1\ncommit_hash: 42449c03\nbuild_time: 2026-08-10 23:10:43 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu")
        .about("Ping, but with a graph.")
        .bin_name("executable")
        .arg(Arg::new("cmd").long("cmd").action(ArgAction::SetTrue).help("Graph the execution time for a list of commands rather than pinging hosts"))
        .arg(Arg::new("watch-interval").short('n').long("watch-interval").value_name("WATCH_INTERVAL").help("Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5"))
        .arg(Arg::new("buffer").short('b').long("buffer").value_name("BUFFER").default_value("30").help("Determines the number of seconds to display in the graph"))
        .arg(Arg::new("ipv4").short('4').action(ArgAction::SetTrue).conflicts_with("ipv6").help("Resolve ping targets to IPv4 address"))
        .arg(Arg::new("ipv6").short('6').action(ArgAction::SetTrue).conflicts_with("ipv4").help("Resolve ping targets to IPv6 address"))
        .arg(Arg::new("interface").short('i').long("interface").value_name("INTERFACE").help("Interface to use when pinging"))
        .arg(Arg::new("simple-graphics").short('s').long("simple-graphics").action(ArgAction::SetTrue).help(""))
        .arg(Arg::new("vertical-margin").long("vertical-margin").value_name("VERTICAL_MARGIN").default_value("1").help("Vertical margin around the graph (top and bottom)"))
        .arg(Arg::new("horizontal-margin").long("horizontal-margin").value_name("HORIZONTAL_MARGIN").default_value("0").help("Horizontal margin around the graph (left and right)"))
        .arg(Arg::new("color").short('c').long("color").value_name("color").action(ArgAction::Append).help("Assign color to a graph entry.\n\nThis option can be defined more than once as a comma separated string, and the\norder which the colors are provided will be matched against the hosts or\ncommands passed to gping.\n\nHexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the\nfollowing color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',\n'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',\n'light-blue', 'light-magenta', 'light-cyan', and 'white'"))
        .arg(Arg::new("clear").long("clear").action(ArgAction::SetTrue).help("Clear the graph from the terminal after closing the program"))
        .arg(Arg::new("ping-args").long("ping-args").value_name("PING_ARGS").num_args(0..).allow_hyphen_values(true).help("Extra arguments to pass to `ping`. These are platform dependent"))
        .arg(Arg::new("hosts").value_name("HOSTS_OR_COMMANDS").num_args(0..).help("Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1"))
}

fn is_valid_hex_color(s: &str) -> bool {
    if s.len() != 7 { return false; }
    if !s.starts_with('#') { return false; }
    s[1..].chars().all(|c| c.is_ascii_hexdigit())
}
fn normalize_color(s: &str) -> String {
    let lower = s.to_ascii_lowercase();
    lower.chars().filter(|c| *c != ' ' && *c != '-' && *c != '_' ).collect()
}
fn is_valid_named_color(s: &str) -> bool {
    let trimmed = s.trim_matches(' ');
    if trimmed.is_empty() { return false; }
    let norm = normalize_color(trimmed);
    matches!(norm.as_str(),
        "black" | "red" | "green" | "yellow" | "blue" | "magenta" | "cyan" | "gray" | "grey" | "silver" | "white" |
        "darkgray" | "darkgrey" | "darksilver" |
        "lightblack" | "lightred" | "lightgreen" | "lightyellow" | "lightblue" | "lightmagenta" | "lightcyan" | "lightgray" | "lightgrey" | "lightwhite" | "lightsilver" |
        "brightblack" | "brightred" | "brightgreen" | "brightyellow" | "brightblue" | "brightmagenta" | "brightcyan" | "brightgray" | "brightgrey" | "brightwhite" | "brightsilver"
    )
}
fn is_valid_color_token(raw: &str) -> bool {
    if raw.starts_with('#') {
        return is_valid_hex_color(raw);
    } else if raw.contains('#') {
        return false;
    } else {
        is_valid_named_color(raw)
    }
}

fn main() {
    let mut cmd = build_cli();
    // Manually handle version and help to match original?
    // clap does it automatically, but we need to ensure --version prints long_version for --version and short for -V?
    // Our command has version and long_version, clap will handle.

    let matches = cmd.clone().try_get_matches_from(std::env::args());
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap's error already prints to stderr and exits; need to replicate exit code 2 for clap errors, 0 for help/version
            e.exit();
        }
    };

    let hosts: Vec<String> = matches.get_many::<String>("hosts").map(|v| v.cloned().collect()).unwrap_or_default();
    if hosts.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        std::process::exit(1);
    }

    let is_cmd = matches.get_flag("cmd");
    if is_cmd {
        for h in &hosts {
            if h.trim().is_empty() {
                eprintln!("\nthread 'main' panicked at gping/src/main.rs:269:10:\nMust specify a command to watch\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                std::process::exit(101);
            }
        }
        // check ping-args conflict with cmd
        if matches.contains_id("ping-args") && matches.get_many::<String>("ping-args").is_some() {
            // clap already would have errored, but if we allow, need to error
            // This case shouldn't happen due to conflicts_with, but if user passes --ping-args after hosts, it might be parsed as hosts?
            // Let's explicitly check
            let has_ping_args = matches.get_many::<String>("ping-args").map(|v| v.count() > 0).unwrap_or(false);
            if has_ping_args {
                eprintln!("error: the argument '--cmd' cannot be used with '--ping-args [<PING_ARGS>...]'\n\nUsage: executable --cmd <HOSTS_OR_COMMANDS>...\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    }

    // Parse buffer
    let buffer_str = matches.get_one::<String>("buffer").unwrap();
    let buffer: u64 = match buffer_str.parse() {
        Ok(v) => v,
        Err(_) => {
            eprintln!("error: invalid value '{}' for '--buffer <BUFFER>': invalid digit found in string\n\nFor more information, try '--help'.", buffer_str);
            std::process::exit(2);
        }
    };
    // For our usage, buffer not validated further

    // Parse vertical-margin and horizontal-margin as u64 (allow parsing errors)
    let vertical_str = matches.get_one::<String>("vertical-margin").unwrap();
    if vertical_str.parse::<u64>().is_err() {
        eprintln!("error: invalid value '{}' for '--vertical-margin <VERTICAL_MARGIN>': invalid digit found in string\n\nFor more information, try '--help'.", vertical_str);
        std::process::exit(2);
    }
    let vertical_margin: u64 = vertical_str.parse().unwrap();

    let horizontal_str = matches.get_one::<String>("horizontal-margin").unwrap();
    if horizontal_str.parse::<u64>().is_err() {
        eprintln!("error: invalid value '{}' for '--horizontal-margin <HORIZONTAL_MARGIN>': invalid digit found in string\n\nFor more information, try '--help'.", horizontal_str);
        std::process::exit(2);
    }
    let horizontal_margin: u64 = horizontal_str.parse().unwrap();

    // watch-interval parsing
    let watch_interval_opt = matches.get_one::<String>("watch-interval");
    let watch_interval: f64 = if let Some(s) = watch_interval_opt {
        match s.parse::<f64>() {
            Ok(v) => v,
            Err(_) => {
                eprintln!("error: invalid value '{}' for '--watch-interval <WATCH_INTERVAL>': invalid float literal\n\nFor more information, try '--help'.", s);
                std::process::exit(2);
            }
        }
    } else {
        if is_cmd { 0.5 } else { 0.2 }
    };

    let simple_graphics = matches.get_flag("simple-graphics");
    let _clear = matches.get_flag("clear");
    let _interface: Option<String> = matches.get_one::<String>("interface").cloned();
    let is_ipv4 = matches.get_flag("ipv4");
    let is_ipv6 = matches.get_flag("ipv6");

    let ping_args: Vec<String> = matches.get_many::<String>("ping-args").map(|v| v.cloned().collect()).unwrap_or_default();

    // Check cmd cannot be used with ping-args (clap should have errored, but double-check)
    if is_cmd && !ping_args.is_empty() {
        eprintln!("error: the argument '--cmd' cannot be used with '--ping-args [<PING_ARGS>...]'\n\nUsage: executable --cmd <HOSTS_OR_COMMANDS>...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    // Color validation
    let colors: Vec<String> = matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut flat_colors: Vec<String> = Vec::new();
    for c in &colors {
        for p in c.split(',') {
            flat_colors.push(p.to_string());
        }
    }
    for (i, raw) in flat_colors.iter().enumerate() {
        if i < hosts.len() {
            if !is_valid_color_token(raw) {
                eprintln!("Error: Invalid color code: `{}`\n\nCaused by:\n    Failed to parse Colors", raw);
                std::process::exit(1);
            }
        }
    }

    // AWS expansion
    let mut expanded_hosts: Vec<String> = Vec::new();
    for h in &hosts {
        if h.starts_with("aws:") {
            let region = &h[4..];
            expanded_hosts.push(format!("ec2.{}.amazonaws.com", region));
        } else {
            expanded_hosts.push(h.clone());
        }
    }

    // Host resolution (unless cmd)
    if !is_cmd {
        for (_orig, expanded) in hosts.iter().zip(expanded_hosts.iter()) {
            let addr_str = format!("{}:0", expanded);
            match addr_str.to_socket_addrs() {
                Ok(addrs) => {
                    let addrs_vec: Vec<_> = addrs.collect();
                    let mut has_v4 = false;
                    let mut has_v6 = false;
                    for addr in &addrs_vec {
                        match addr.ip() {
                            IpAddr::V4(_) => has_v4 = true,
                            IpAddr::V6(_) => has_v6 = true,
                        }
                    }
                    if is_ipv4 && !has_v4 {
                        eprintln!("Error: Could not resolve '{}' to IPv4", expanded);
                        std::process::exit(1);
                    }
                    if is_ipv6 && !has_v6 {
                        eprintln!("Error: Could not resolve '{}' to IPv6", expanded);
                        std::process::exit(1);
                    }
                    if addrs_vec.is_empty() {
                        eprintln!("Error: Resolving {}\n\nCaused by:\n    failed to lookup address information: Name or service not known", expanded);
                        std::process::exit(1);
                    }
                },
                Err(e) => {
                    eprintln!("Error: Resolving {}\n\nCaused by:\n    {}", expanded, e);
                    std::process::exit(1);
                }
            }
        }
    }

    // Ping version detection (only for ping mode)
    if !is_cmd {
        let ping_check = Command::new("ping").arg("-V").output();
        match ping_check {
            Ok(output) => {
                let stdout = String::from_utf8_lossy(&output.stdout);
                let stderr = String::from_utf8_lossy(&output.stderr);
                let combined = format!("{} {}", stdout, stderr).to_ascii_lowercase();
                if combined.contains("inetutils") {
                    eprintln!("Error: Installed ping is not supported: Please use iputils ping, not inetutils.");
                    std::process::exit(1);
                }
                if !combined.contains("iputils") {
                    let stdout_lines: Vec<String> = stdout.lines().map(|s| s.to_string()).collect();
                    let stderr_lines: Vec<String> = stderr.lines().map(|s| s.to_string()).collect();
                    eprintln!("Error: Could not detect ping. Stderr: {:?}\nStdout: {:?}", stderr_lines, stdout_lines);
                    std::process::exit(1);
                }
            },
            Err(e) => {
                eprintln!("Error: Error spawning ping: {}\n\nCaused by:\n    {}", e, e);
                std::process::exit(1);
            }
        }
        let mut needs_ping6 = false;
        if is_ipv6 {
            needs_ping6 = true;
        } else {
            for host in &expanded_hosts {
                if host.contains(':') {
                    needs_ping6 = true;
                    break;
                }
                if let Ok(ip) = host.parse::<IpAddr>() {
                    if matches!(ip, IpAddr::V6(_)) {
                        needs_ping6 = true;
                        break;
                    }
                }
            }
        }
        if needs_ping6 {
            let ping6_check = Command::new("ping6").arg("-V").output();
            match ping6_check {
                Ok(_) => {},
                Err(e) => {
                    eprintln!("Error: Error spawning ping: {}\n\nCaused by:\n    {}", e, e);
                    std::process::exit(1);
                }
            }
        }
    }

    // Terminal check
    if let Err(e) = crossterm::terminal::enable_raw_mode() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
    let _ = crossterm::terminal::disable_raw_mode();

    // Prepare to run TUI
    let clear = matches.get_flag("clear");

    let mut children = Vec::new();
    if !is_cmd {
        for host in &expanded_hosts {
            let ping_bin = if is_ipv6 {
                "ping6"
            } else if host.contains(':') {
                "ping6"
            } else if let Ok(ip) = host.parse::<IpAddr>() {
                match ip {
                    IpAddr::V6(_) => "ping6",
                    _ => "ping",
                }
            } else {
                "ping"
            };
            let mut cmd_args: Vec<String> = Vec::new();
            cmd_args.push("-O".to_string());
            let interval_str = format!("{:?}", watch_interval);
            // The original for 0.2 gives "0.2" but format!("{:?}", 0.2) gives "0.2", for 1.0 gives "1.0", good
            // But for 0.5? It gives "0.5"
            cmd_args.push(format!("-i{}", interval_str));
            if let Some(ref iface) = _interface {
                cmd_args.push("-I".to_string());
                cmd_args.push(iface.clone());
            }
            for pa in &ping_args {
                cmd_args.push(pa.clone());
            }
            cmd_args.push(host.clone());
            let child = Command::new(ping_bin)
                .args(&cmd_args)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn();
            match child {
                Ok(c) => children.push(c),
                Err(e) => {
                    eprintln!("Error: Error spawning ping: {}\n\nCaused by:\n    {}", e, e);
                    std::process::exit(1);
                }
            }
        }
    } else {
        // cmd mode: no ping children
    }

    if let Err(e) = run_tui(&hosts, buffer, vertical_margin, horizontal_margin, watch_interval, is_cmd, clear) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }

    for mut child in children {
        let _ = child.kill();
        let _ = child.wait();
    }

    if clear {
        use crossterm::execute;
        use crossterm::terminal::{Clear, ClearType};
        let _ = execute!(std::io::stdout(), Clear(ClearType::All));
    }
}

fn run_tui(hosts: &[String], buffer: u64, vertical_margin: u64, horizontal_margin: u64, watch_interval: f64, is_cmd: bool, _clear: bool) -> anyhow::Result<()> {
    use crossterm::{
        event::{self, Event, KeyCode},
        execute,
        terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Constraint, Direction, Layout},
        widgets::{Block, Borders, Paragraph},
        Terminal,
    };
    use std::io;
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    let mut should_quit = false;
    while !should_quit {
        terminal.draw(|f| {
            let size = f.area();
            let vertical = vertical_margin as u16;
            let horizontal = horizontal_margin as u16;
            let inner = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(vertical),
                    Constraint::Min(0),
                    Constraint::Length(vertical),
                ])
                .split(size);
            let middle = inner[1];
            let horiz = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Length(horizontal),
                    Constraint::Min(0),
                    Constraint::Length(horizontal),
                ])
                .split(middle);
            let area = horiz[1];
            let block = Block::default().title("gping").borders(Borders::ALL);
            let mode = if is_cmd { "cmd" } else { "ping" };
            let hosts_text = hosts.join(", ");
            let paragraph = Paragraph::new(format!("Mode: {}\nHosts: {}\nBuffer: {}s Interval: {}s\nPress 'q' to quit", mode, hosts_text, buffer, watch_interval))
                .block(block);
            f.render_widget(paragraph, area);
        })?;
        let timeout = Duration::from_secs_f64(watch_interval);
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                    should_quit = true;
                }
                if key.code == KeyCode::Char('c') && key.modifiers.contains(event::KeyModifiers::CONTROL) {
                    should_quit = true;
                }
            }
        }
    }
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}
RS

