    while time.time()-start < timeout:
        r,_,_=select.select([master],[],[],0.2)
        if r:
            try:
                chunk=os.read(master,8192)
                if not chunk: break
                data+=chunk
            except: break
        if proc.poll() is not None:
            time.sleep(0.3)
            try:
                while True:
                    r,_,_=select.select([master],[],[],0.1)
                    if not r: break
                    chunk=os.read(master,8192)
                    if not chunk: break
                    data+=chunk
            except: pass
